import { Injectable } from '@angular/core';
import { Router } from '@angular/router';
import { BehaviorSubject, Observable, of } from 'rxjs';
import { tap, map, catchError } from 'rxjs/operators';
import { AuthService as ApiAuthService } from '../api/api/auth.service';
import { UsersService as ApiUsersService } from '../api/api/users.service';
import { UserLoginRequestDto, UserLoginResponseDto, UserPostRequestDto } from '../api'; // Assuming models are exported from api/index.ts

@Injectable({
  providedIn: 'root',
})
export class AuthService {
  private currentUserSubject = new BehaviorSubject<UserLoginResponseDto | null>(null);
  public currentUser = this.currentUserSubject.asObservable();
  private readonly TOKEN_KEY = 'authToken';

  constructor(
    private router: Router,
    private apiAuthService: ApiAuthService,
    private apiUsersService: ApiUsersService
  ) {
    this.loadToken(); // Try to load token on service initialization
  }

  private loadToken(): void {
    const token = this.getToken();
    if (token) {
      // In a real app, you would validate the token with the backend here
      // and fetch user details if the token is valid.
      // For now, we'll assume if a token exists, it's for a logged-in user.
      // We don't have the full UserLoginResponseDto, so we can't populate currentUserSubject
      // without an API call. For isAuthenticated, just checking token existence is enough for now.
      // If you need user info throughout the app from local storage, consider storing a minimal User object.
    }
  }

  login(credentials: UserLoginRequestDto): Observable<UserLoginResponseDto> {
    return this.apiAuthService.login(credentials).pipe(
      tap((response: UserLoginResponseDto) => {
        if (response && response.accessToken) {
          localStorage.setItem(this.TOKEN_KEY, response.accessToken);
          // To keep things simple, we don't store the whole user object from login in currentUserSubject directly
          // as it might become stale. Instead, isAuthenticated relies on the token.
          // A dedicated user profile service could fetch and manage user data.
          this.currentUserSubject.next(response); // Or a subset of it
          this.router.navigate(['/home']);
        }
      }),
      catchError(err => {
        console.error('Login failed', err);
        // Clear any existing token on login failure
        localStorage.removeItem(this.TOKEN_KEY);
        this.currentUserSubject.next(null);
        throw err; // Re-throw the error to be caught by the component
      })
    );
  }

  register(userData: UserPostRequestDto): Observable<any> { // Adjust 'any' to specific DTO if available
    return this.apiUsersService.postUser(userData).pipe(
      tap(() => {
        this.router.navigate(['/login']);
      }),
      catchError(err => {
        console.error('Registration failed', err);
        throw err; // Re-throw the error
      })
    );
  }

  logout(): void {
    localStorage.removeItem(this.TOKEN_KEY);
    this.currentUserSubject.next(null);
    this.router.navigate(['/login']);
  }

  getToken(): string | null {
    return localStorage.getItem(this.TOKEN_KEY);
  }

  isAuthenticated(): boolean {
    const token = this.getToken();
    // Basic check: does a token exist?
    // In a real app: decode token, check expiry, etc.
    return !!token;
  }

  // Optional: If you need to access the current user's data stored from login
  public get currentUserValue(): UserLoginResponseDto | null {
    return this.currentUserSubject.value;
  }
}

import { Inject, Injectable, Optional }                      from '@angular/core';
import { HttpClient, HttpHeaders, HttpParams,
         HttpResponse, HttpEvent, HttpParameterCodec, HttpContext 
        }       from '@angular/common/http';
import { CustomHttpParameterCodec }                          from '../encoder';
import { Observable }                                        from 'rxjs';

// @ts-ignore
import { ErrorResponseDto } from '../model/error-response-dto';
// @ts-ignore
import { UserLoginRequestDto } from '../model/user-login-request-dto';
// @ts-ignore
import { UserLoginResponseDto } from '../model/user-login-response-dto';

// @ts-ignore
import { BASE_PATH, COLLECTION_FORMATS }                     from '../variables';
import { Configuration }                                     from '../configuration';



@Injectable({
  providedIn: 'root'
})
export class AuthService {

    protected basePath = 'https://localhost:3000/api/v1';
    public defaultHeaders = new HttpHeaders();
    public configuration = new Configuration();
    public encoder: HttpParameterCodec;

    constructor(protected httpClient: HttpClient, @Optional()@Inject(BASE_PATH) basePath: string|string[], @Optional() configuration: Configuration) {
        if (configuration) {
            this.configuration = configuration;
        }
        if (typeof this.configuration.basePath !== 'string') {
            const firstBasePath = Array.isArray(basePath) ? basePath[0] : undefined;
            if (firstBasePath != undefined) {
                basePath = firstBasePath;
            }

            if (typeof basePath !== 'string') {
                basePath = this.basePath;
            }
            this.configuration.basePath = basePath;
        }
        this.encoder = this.configuration.encoder || new CustomHttpParameterCodec();
    }


    // @ts-ignore
    private addToHttpParams(httpParams: HttpParams, value: any, key?: string): HttpParams {
        if (typeof value === "object" && value instanceof Date === false) {
            httpParams = this.addToHttpParamsRecursive(httpParams, value);
        } else {
            httpParams = this.addToHttpParamsRecursive(httpParams, value, key);
        }
        return httpParams;
    }

    private addToHttpParamsRecursive(httpParams: HttpParams, value?: any, key?: string): HttpParams {
        if (value == null) {
            return httpParams;
        }

        if (typeof value === "object") {
            if (Array.isArray(value)) {
                (value as any[]).forEach( elem => httpParams = this.addToHttpParamsRecursive(httpParams, elem, key));
            } else if (value instanceof Date) {
                if (key != null) {
                    httpParams = httpParams.append(key, (value as Date).toISOString().substring(0, 10));
                } else {
                   throw Error("key may not be null if value is Date");
                }
            } else {
                Object.keys(value).forEach( k => httpParams = this.addToHttpParamsRecursive(
                    httpParams, value[k], key != null ? `${key}.${k}` : k));
            }
        } else if (key != null) {
            httpParams = httpParams.append(key, value);
        } else {
            throw Error("key may not be null if value is not object or array");
        }
        return httpParams;
    }

    /**
     * ログイン
     * メールアドレスとパスワードを使用してユーザーを認証し、アクセストークンを返す
     * @param userLoginRequestDto 
     * @param observe set whether or not to return the data Observable as the body, response or events. defaults to returning the body.
     * @param reportProgress flag to report request and response progress.
     */
    public login(userLoginRequestDto: UserLoginRequestDto, observe?: 'body', reportProgress?: boolean, options?: {httpHeaderAccept?: 'application/json', context?: HttpContext, transferCache?: boolean}): Observable<UserLoginResponseDto>;
    public login(userLoginRequestDto: UserLoginRequestDto, observe?: 'response', reportProgress?: boolean, options?: {httpHeaderAccept?: 'application/json', context?: HttpContext, transferCache?: boolean}): Observable<HttpResponse<UserLoginResponseDto>>;
    public login(userLoginRequestDto: UserLoginRequestDto, observe?: 'events', reportProgress?: boolean, options?: {httpHeaderAccept?: 'application/json', context?: HttpContext, transferCache?: boolean}): Observable<HttpEvent<UserLoginResponseDto>>;
    public login(userLoginRequestDto: UserLoginRequestDto, observe: any = 'body', reportProgress: boolean = false, options?: {httpHeaderAccept?: 'application/json', context?: HttpContext, transferCache?: boolean}): Observable<any> {
        if (userLoginRequestDto === null || userLoginRequestDto === undefined) {
            throw new Error('Required parameter userLoginRequestDto was null or undefined when calling login.');
        }

        let localVarHeaders = this.defaultHeaders;

        let localVarHttpHeaderAcceptSelected: string | undefined = options && options.httpHeaderAccept;
        if (localVarHttpHeaderAcceptSelected === undefined) {
            // to determine the Accept header
            const httpHeaderAccepts: string[] = [
                'application/json'
            ];
            localVarHttpHeaderAcceptSelected = this.configuration.selectHeaderAccept(httpHeaderAccepts);
        }
        if (localVarHttpHeaderAcceptSelected !== undefined) {
            localVarHeaders = localVarHeaders.set('Accept', localVarHttpHeaderAcceptSelected);
        }

        let localVarHttpContext: HttpContext | undefined = options && options.context;
        if (localVarHttpContext === undefined) {
            localVarHttpContext = new HttpContext();
        }

        let localVarTransferCache: boolean | undefined = options && options.transferCache;
        if (localVarTransferCache === undefined) {
            localVarTransferCache = true;
        }


        // to determine the Content-Type header
        const consumes: string[] = [
            'application/json'
        ];
        const httpContentTypeSelected: string | undefined = this.configuration.selectHeaderContentType(consumes);
        if (httpContentTypeSelected !== undefined) {
            localVarHeaders = localVarHeaders.set('Content-Type', httpContentTypeSelected);
        }

        let responseType_: 'text' | 'json' | 'blob' = 'json';
        if (localVarHttpHeaderAcceptSelected) {
            if (localVarHttpHeaderAcceptSelected.startsWith('text')) {
                responseType_ = 'text';
            } else if (this.configuration.isJsonMime(localVarHttpHeaderAcceptSelected)) {
                responseType_ = 'json';
            } else {
                responseType_ = 'blob';
            }
        }

        let localVarPath = `/auth/login`;
        return this.httpClient.request<UserLoginResponseDto>('post', `${this.configuration.basePath}${localVarPath}`,
            {
                context: localVarHttpContext,
                body: userLoginRequestDto,
                responseType: <any>responseType_,
                withCredentials: this.configuration.withCredentials,
                headers: localVarHeaders,
                observe: observe,
                transferCache: localVarTransferCache,
                reportProgress: reportProgress
            }
        );
    }

}

